<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>The Great Wave off Kanagawa - low poly wallpaper</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#efe3c6}
  canvas{display:block}
  #cap{position:fixed;left:16px;bottom:12px;font:12px/1.4 Georgia,serif;color:#2b3a55;opacity:.75;pointer-events:none}
</style>
</head>
<body>
<div id="cap">The Great Wave off Kanagawa &mdash; after Katsushika Hokusai (public domain), rebuilt as a low-poly scene</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// ---- palette taken from the print ----
const C = {
  paper: 0xefe3c6,   // aged washi
  deep:  0x1d3a6e,   // deep prussian blue (wave bodies)
  mid:   0x2f5d9e,   // mid blue
  pale:  0xa8c8e0,   // pale blue (foam shading)
  foam:  0xf3f0e4,   // white foam
  hull:  0xd99a5b,   // ochre / tan hulls
  hull2: 0xb97a3f,   // darker hull
  skin:  0xe8c9a0,   // rowers' skin
  fuji:  0x3a5a8c,   // Fuji blue slope
  snow:  0xf5f2e8,   // Fuji snow cap
  sky:   0xe9dcc0,   // sky wash
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
scene.fog = new THREE.Fog(C.paper, 60, 160);

const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, .1, 400);
camera.position.set(0, 7, 46);
camera.lookAt(0, 4, 0);

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const flat = (c, e=1) => new THREE.MeshLambertMaterial({color:c, flatShading:true, emissive:c, emissiveIntensity:.35*e});
scene.add(new THREE.AmbientLight(0xffffff, .9));
const sun = new THREE.DirectionalLight(0xfff2d8, 1.1);
sun.position.set(-20, 30, 20);
scene.add(sun);

// =========================================================
// The Great Wave: a curling cone of stacked rings, left side
// =========================================================
const wave = new THREE.Group();
scene.add(wave);

// curl profile: a series of torus-like rings sweeping up and over
// center of curl at x=-14, rising to y=16, lip curling right
const RINGS = 26;
for (let i=0;i<RINGS;i++){
  const t = i/(RINGS-1);
  const y = 2 + t*13;                 // height up the wall
  const x = -14 + t*10;               // leaning right as it rises
  const r = 16 - t*11;                // radius shrinking toward the lip
  const seg = 10 + (i%2)*2;           // low-poly facets, alternating
  const geo = new THREE.TorusGeometry(r, 1.1 - t*.55, 4, seg, Math.PI*1.35);
  const col = (i%5===0) ? C.pale : (i%2 ? C.deep : C.mid);
  const m = new THREE.Mesh(geo, flat(col));
  m.position.set(x, y, -6 - t*2);
  m.rotation.z = -0.5 + t*1.15;       // sweep from wall to overhanging lip
  m.rotation.y = 0.25;
  wave.add(m);
}
// foam "claws": white spiky cones at the lip
function claws(x,y,z,n,spread,up){
  for(let i=0;i<n;i++){
    const a = -0.6 + (i/(n-1))*spread;
    const g = new THREE.ConeGeometry(.55, 2.2+Math.random()*1.4, 4);
    const m = new THREE.Mesh(g, flat(C.foam));
    m.position.set(x+Math.cos(a)*6, y+Math.sin(a)*3, z);
    m.rotation.set(0,0, a + (up?-.4:.4));
    wave.add(m);
  }
}
claws(-4, 15.5, -7, 9, 2.4, true);
claws(-10, 12, -8, 7, 1.8, true);

// foam dots scattered on the wave face (the print's white specks)
for(let i=0;i<60;i++){
  const t=Math.random();
  const g=new THREE.SphereGeometry(.28+Math.random()*.3, 4, 3);
  const m=new THREE.Mesh(g, flat(C.foam));
  m.position.set(-14+t*12, 2+t*13+Math.random()*1.5-0.75, -6-t*2+Math.random()*2-1);
  wave.add(m);
}

